<?php ob_start(); ?><h1><?= e(t('Threat IPs')) ?></h1><p class="muted"><?= e(t('A manually curated list of attacker IPs seen in suspicious log events or found while investigating findings. Classify each IP so future investigations are faster; this list does not block traffic by itself.')) ?></p>
<div class="card"><h2><?= e(t('Add / update IP')) ?></h2><form method="post" action="/threat-ips/save"><p><input class="input" name="ip" placeholder="1.2.3.4" value="<?= e($prefillIp) ?>" required> <select class="input" name="classification"><?php foreach($classifications as $c): ?><option value="<?= e($c) ?>"><?= e(t($c)) ?></option><?php endforeach ?></select> <select class="input" name="risk"><?php foreach(['low','medium','high','critical'] as $r): ?><option value="<?= e($r) ?>" <?= $r==='medium'?'selected':'' ?>><?= e(t($r)) ?></option><?php endforeach ?></select></p><p><textarea class="input" name="notes" rows="2" cols="80" placeholder="<?= e(t('Notes: what was seen, which sites/findings, dates...')) ?>"></textarea></p><button class="btn"><?= e(t('Save')) ?></button></form></div>
<table><tr><th>IP</th><th><?= e(t('Classification')) ?></th><th><?= e(t('Risk')) ?></th><th><?= e(t('Notes')) ?></th><th><?= e(t('Hits')) ?></th><th><?= e(t('First seen')) ?></th><th><?= e(t('Last seen')) ?></th><th><?= e(t('Actions')) ?></th></tr><?php foreach($ips as $i): ?><tr><td><code><?= e($i['ip']) ?></code></td><td><?= e(t($i['classification'])) ?></td><td><span class="badge <?= e($i['risk']) ?>"><?= e(t($i['risk'])) ?></span></td><td><?= e($i['notes']) ?></td><td><?= e($i['hit_count']) ?></td><td><?= e($i['first_seen_at']) ?></td><td><?= e($i['last_seen_at']) ?></td><td><a class="btn small" href="/logs?ip=<?= urlencode($i['ip']) ?>"><?= e(t('View logs')) ?></a> <a class="btn small" href="/threat-ips/abuse-report?ip=<?= urlencode($i['ip']) ?>"><?= e(t('Abuse report')) ?></a> <form method="post" action="/threat-ips/delete" style="display:inline" onsubmit="return confirm(<?= e(json_encode(t('Remove this IP from the list?'))) ?>)"><input type="hidden" name="id" value="<?= e($i['id']) ?>"><button class="btn danger small"><?= e(t('Delete')) ?></button></form></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
